import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"Knowledge and retrieval","description":"","frontmatter":{"title":"Knowledge and retrieval"},"headers":[],"relativePath":"guide/knowledge.md","filePath":"guide/knowledge.md"}'),r={name:"guide/knowledge.md"};function o(l,e,d,s,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="knowledge-and-retrieval" tabindex="-1">Knowledge and retrieval <a class="header-anchor" href="#knowledge-and-retrieval" aria-label="Permalink to &quot;Knowledge and retrieval&quot;">​</a></h1><p>A knowledge base provides retrievable reference material to agents or workflows. It does not simply pass an entire document to a model.</p><h2 id="create-a-knowledge-base" tabindex="-1">Create a knowledge base <a class="header-anchor" href="#create-a-knowledge-base" aria-label="Permalink to &quot;Create a knowledge base&quot;">​</a></h2><ol><li>Open knowledge management and create a named, described knowledge base.</li><li>Upload material you are authorized to use. Check it for secrets, personal data and content unsuitable for external models.</li><li>Select text or vector retrieval and configure chunking and retrieval options in the current interface.</li><li>For vector retrieval, select the appropriate LLM/embedding model configuration and vector storage; options depend on the deployment.</li><li>Wait for indexing, inspect chunks or retrieval results, then assign the base to an agent.</li></ol><p>Text and vector retrieval have different model dependencies. An uploaded file does not prove that indexing, embedding or retrieval is ready.</p><h2 id="use-it-with-an-agent" tabindex="-1">Use it with an agent <a class="header-anchor" href="#use-it-with-an-agent" aria-label="Permalink to &quot;Use it with an agent&quot;">​</a></h2><ol><li>Select the base in the agent&#39;s <strong>Knowledge</strong> section.</li><li>Save and ask a question whose answer can be verified from the material.</li><li>Check the answer against the source and inspect retrieved chunks or traces where available.</li><li>After updating material, check indexing again rather than assuming new content is already active.</li></ol><p>For explicit workflow queries, use the <a href="./../knowledge_retrieval.html">knowledge retrieval node</a>. Vector, keyword and hybrid methods are available; AI summaries require the corresponding model configuration.</p><h2 id="permissions-and-data" tabindex="-1">Permissions and data <a class="header-anchor" href="#permissions-and-data" aria-label="Permalink to &quot;Permissions and data&quot;">​</a></h2><ul><li>Review provider data handling before sending chunks to an external model.</li><li>Do not combine material with different confidentiality requirements in one shared base.</li><li>Retrievable content is not necessarily true. Instructions in external documents remain untrusted input.</li><li>Check agent and workflow references before deleting or changing a base.</li></ul>',10)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
